<div class="page-heading"><div><h1>Record reviews</h1><p>Issues raised by executive reviewers. Correct records through their usual editors, then mark the issue resolved.</p></div></div><section class="card card-body"><?php foreach($rows as $row): ?><article class="border-bottom pb-3 mb-3"><h2 class="h5"><?= e($row['full_name']??'Person record removed') ?></h2><p class="small text-secondary">Raised by <?= e($row['actor']) ?> · <?= e(date_display($row['created_at'],true)) ?> UTC</p><p class="text-break"><?= nl2br(e(\App\Crypto::decrypt($row['note_encrypted']))) ?></p><?php if($row['voter_record_id']): ?><a class="btn btn-sm btn-light" href="<?= e(url('voter',['id'=>$row['voter_record_id']])) ?>">Open record</a><?php endif; ?><form class="d-inline" action="<?= e(url()) ?>" method="post"><?= csrf() ?><input type="hidden" name="_action" value="review_resolve"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="btn btn-sm btn-outline-success">Mark resolved</button></form></article><?php endforeach; ?><?php if(!$rows): ?><p>No open reviews.</p><?php endif; ?><div><?= number($total) ?> open · Page <?= $p ?> of <?= $last ?> <?php if($p>1): ?><a href="<?= e(url('record_reviews',['p'=>$p-1])) ?>">Previous</a><?php endif; ?> <?php if($p<$last): ?><a href="<?= e(url('record_reviews',['p'=>$p+1])) ?>">Next</a><?php endif; ?></div></section>
